      "desc": "你太孤独了。\r\n\r\n但你不敢承认。你把自己塞进人群里，参加聚会、刷朋友圈、找人聊天。你把时间填满，把脑子填满，把心填满。满到没有缝隙，就不必面对那个空。\r\n\r\n隐士逆位不是来骂你怕孤独。他是来告诉你：你逃不掉的。那个空，是你自己的房间。你迟早要回去住。",
