      "desc": "你堵住了耳朵。\r\n\r\n那声音还在喊，但你不听。你把自己埋在更深的梦里，盖三层被子，拉上窗帘，把闹钟扔到床底下。你以为这样就听不见了。但你听见了心跳，咚咚咚，那也是喊你的声音。\r\n\r\n审判逆位不是来骂你装睡的。他是来告诉你：你装不了多久了。 声音会越来越大，大到从梦里把你拽出来。那时候你醒得更疼。",
