      "desc": "你们不看对方了。\r\n\r\n杯子碰在一起，但眼睛看向别处。你想他看你看得不够，他想你想他想得太多。你们都在等对方先转过来，但谁都不转。\r\n\r\n圣杯二逆位不是来告诉你“他不爱你了”。他是来问你：你们什么时候开始平行的？\r\n\r\n平行的人，可以一起走，但永远看不见对方的眼睛。你想看见他，就得先转过来。",
      "core": "你们什么时候开始平行的？",
      "action": "今天，转过来一次。不管谁对谁错，不管之前怎样，先看他一眼。就一眼，他会看见的。"
