        "行动": {
          "desc": "圣杯侍从说：行动就是低头看一眼鱼。",
          "core": "",
          "action": ""
        },
        "环境": {
          "desc": "周围都是忙的人。你停下来看鱼，他们会说你闲。但你看鱼的时候，心里有光。",
          "core": "",
          "action": ""
        },
        "希望/恐惧": {
          "desc": "你希望能保持童心，又怕童心是幼稚。圣杯侍从说：童心不是幼稚，是看见世界本来的样子。",
          "core": "",
          "action": ""
        }
