      "desc": "你输了。\r\n\r\n不是没打过，是打完之后，你发现自己站在输的那一边。他们拿着战利品走了，你留在原地，一身伤，两手空。\r\n\r\n宝剑五逆位不是来让你沮丧的。他是来告诉你：有些输，比赢好。\r\n\r\n输的人，至少不用背那些赢回来的负担。你空着手，反而可以重新开始。而那些赢的人，手里拿着的，可能是再也没法还给你的。",
      "core": "有些输，比赢好。",
      "action": "今天，想想你最近输的一场“战争”。不是为了后悔，就问问自己：输完之后，我有没有学到什么？"
