      "desc": "你偷偷拿走了五把剑，留下两把。\r\n\r\n不是偷别人的，是你自己的剑。你从一场战争里悄悄退出，带着你还能带走的，留下你带不动的。别人可能骂你逃兵，但你知道，有些仗，不打了就是赢。\r\n\r\n宝剑七不是来让你光荣撤退的。他是来问你：你拿走的那五把剑，能帮你活吗？\r\n\r\n能活，就够了。剩下的，让别人捡去吧。",
