      "desc": "你乱砍了。\r\n\r\n不是决断，是冲动。你没看清，没想清楚，就举剑砍下去了。砍完之后，你发现砍错了，但已经晚了。你怪别人，怪运气，但你知道，怪的是自己。\r\n\r\n宝剑国王逆位不是来让你后悔的。他是来告诉你：停下来，再看一遍。\r\n\r\n你太急了。急的人，看不清。你需要的不是剑，是时间。",
