      "sub": "金币掉地上了",
      "desc": "金币掉地上了。\r\n\r\n不是你没接住，是你不想接。你觉得太小，太少，不够好。你在等更大的金币，更好的机会。但等的时候，这个已经滚远了。\r\n\r\n星币王牌逆位不是来骂你贪心的。他是来问你：你非要等那个“最好的”吗？\r\n\r\n最好的，是现在这个。你不接，它就没了。",
