      "desc": "绳子松了。\r\n\r\n不是别人解的，是你自己挣开的。你睁开眼睛，看见那些剑，其实离你很远。它们一直在那，但你之前看不见。现在你看见了，就不怕了。\r\n\r\n宝剑八逆位不是来夸你勇敢的。他是来告诉你：你从来就不是囚徒。你只是以为自己是个囚徒。\r\n\r\n现在你知道自己自由了。你可以走了。",
